\begin{lemma}[The native quotient over the whole punctured cusp]
\hypertarget{tag-0370}{}\label{wb:cusp-cone-native-descent}
\StatementRecord{wb:cusp-cone-native-descent}{proved}{0370}{\SeriesRef{wb:cusp-spec-native-quotient}}

There is a well-defined real-analytic fibrewise group epimorphism
\begin{equation}
 \overline\pi:N_0\setminus W
 \longrightarrow D_0^*\times\overline T^2
 \hypertarget{tag-0371}{}\label{wb:cusp-cone-native-family-map}
\end{equation}
whose kernel is the connected two-torus family defined by \(K_\Lambda\).
The target local system is trivial.  On the positive radial fibre \(F_T\),
\(t=e^{-2\pi T}\), the isomorphism
\begin{equation}
 \iota_T:\overline T^2\longrightarrow Q_T,\qquad
 [(a,b)]\longmapsto[Y_T(a,b)^{\mathsf T}]
 \hypertarget{tag-037G}{}\label{wb:cusp-cone-radial-isometry}
\end{equation}
satisfies
\begin{equation}
 \pi_T=\iota_T\circ\overline\pi|_{F_T}.
 \hypertarget{tag-0372}{}\label{wb:cusp-cone-native-restriction}
\end{equation}
If \(\overline T^2\) is given the pullback by \(\iota_T\) of the
Euclidean quotient metric on \(Q_T=\mathbb R^2/Y_T\mathbb Z^2\), then
\(\iota_T\) is an isometry and
\begin{equation}
 \operatorname{sys}(\overline T^2,g_T)
 =\operatorname{sys}(Q_T)\geq T-C.
 \hypertarget{tag-0373}{}\label{wb:cusp-cone-native-systole}
\end{equation}
\end{lemma}



\begin{proof}
\begin{enumerate}[label={$\langle1\rangle$\arabic*.},leftmargin=*]
\item On the universal cover of \(D_0^*\), use the real-analytic flat marking
\[
 (z,x+\Lambda)\longmapsto[z,\Pi(z)x].
\]
The deck generator acts by
\[
 (z,x+\Lambda)\longmapsto(g_0z,M_0x+\Lambda).
\]
The displayed matrix \(M_0\) gives
\begin{equation}
 (M_0-I)(a,b,c,d)^{\mathsf T}=(0,0,b,-a)^{\mathsf T},\qquad
 \operatorname{im}(M_0-I)=K_\Lambda.
 \hypertarget{tag-036X}{}\label{wb:cusp-cone-monodromy-image}
\end{equation}
Consequently \(M_0\) preserves \(K_\Lambda\) and induces the identity on
\(\overline\Lambda\).  The formula
\[
 [z,\Pi(z)x]\longmapsto
 \bigl([z],[x\bmod K_\Lambda]\bigr)
\]
is invariant under the deck action and proves
\cref{wb:cusp-cone-native-family-map}.  The lattice \(K_\Lambda\) is primitive,
so the kernel is connected.  On the radial fibre, projection to the
\((e_2,e_4)\)-coordinates sends
\(a\widehat\gamma+b\widehat u\) to \(Y_T(a,b)^{\mathsf T}\) and kills
\(K_\Lambda\).  This proves
\cref{wb:cusp-cone-radial-isometry} and \cref{wb:cusp-cone-native-restriction}.  The metric
and systolic assertion is the quotient calculation in
\cref{wb:cusp-spec-native-quotient}.
\end{enumerate}
\end{proof}

\begin{proposition}[Localized \(S^{24}\) route with target
\(\operatorname{Susp}(T^2)^{\wedge4}\)]
\hypertarget{tag-0365}{}\label{wb:cusp-cone-S24-local-route}
\StatementRecord{wb:cusp-cone-S24-local-route}{proved}{0365}{\SeriesRef{wb:cusp-cone-S24-R4-limit}, \SeriesRef{wb:cusp-cone-S12-route}}

There is a continuous surjective based quotient map
\begin{equation}
 q_{1,\mathrm{cusp}}:(X,x_0)\longrightarrow(\mathcal B,b_0)
 \hypertarget{tag-037B}{}\label{wb:cusp-cone-q1-local}
\end{equation}
given by
\begin{equation}
 q_{1,\mathrm{cusp}}(x)
 =[r,e^{i\phi},\theta_\gamma(x)]
 \quad(0<|t|=r<\epsilon),\qquad
 q_{1,\mathrm{cusp}}(W)=b_0,\qquad
 q_{1,\mathrm{cusp}}
 \bigl(X\setminus\operatorname{int}N_0\bigr)=b_1.
 \hypertarget{tag-037C}{}\label{wb:cusp-cone-q1-local-formula}
\end{equation}
Its fourth smash power has source \(X^{\wedge4}\cong S^{24}\), and on
four synchronized radial fibres it is exactly
\begin{equation}
 \chi_{\gamma,T}^{\times4}:F_T^4\longrightarrow C_T^4.
 \hypertarget{tag-0364}{}\label{wb:cusp-cone-S24-local-fibre-map}
\end{equation}
Consequently its intrinsic target slices satisfy the Euclidean limit
\cref{wb:cusp-cone-S24-R4-limit}.  The target homology is
\begin{equation}
 \widetilde H_k(\mathcal B;\mathbb Z)\cong
 \begin{cases}
  \mathbb Z^2,&k=2,\\
  \mathbb Z,&k=3,\\
  0,&\text{otherwise},
 \end{cases}
 \hypertarget{tag-035A}{}\label{wb:cusp-cone-B-homology}
\end{equation}
and
\begin{equation}
 \widetilde H_k(\mathcal B^{\wedge4};\mathbb Z)\cong
 \begin{cases}
  \mathbb Z^{16},&k=8,\\
  \mathbb Z^{32},&k=9,\\
  \mathbb Z^{24},&k=10,\\
  \mathbb Z^8,&k=11,\\
  \mathbb Z,&k=12,\\
  0,&\text{otherwise}.
 \end{cases}
 \hypertarget{tag-035B}{}\label{wb:cusp-cone-B-smash-homology}
\end{equation}
\end{proposition}



\begin{proof}
\begin{enumerate}[label={$\langle1\rangle$\arabic*.},leftmargin=*]
\item The monodromy invariance
\(\varepsilon_\gamma M_0=\varepsilon_\gamma\) makes the interior formula
single-valued after a turn in the base angle.  The two endpoint-continuity
arguments are identical to those in the proof of
\cref{wb:cusp-cone-S12-route}, with compact cross-section \(T^2\) in place of
\(T^3\).  Fibrewise surjectivity of \(\theta_\gamma\), together with the
nonempty inner fibre and exterior, proves surjectivity.  Compact-to-Hausdorff
makes the map a quotient map.

\item Since \(x_0\in W\), the fourth smash power exists.  The radial regular
fibres and their circle targets avoid the two closed fat wedges.  The
restrictions of the Hausdorff smash quotients to these compact subspaces are
continuous and one-to-one, hence embeddings, and the fibre map is exactly
\cref{wb:cusp-cone-S24-local-fibre-map}.  The intrinsic metric statement is
therefore the four-circle calculation
\cref{wb:cusp-cone-S24-R4-limit}.  Finally, suspension shifts the free homology
of \(T^2\), giving \cref{wb:cusp-cone-B-homology}.  In the fourth smash power,
choosing \(j\) of the four factors in degree \(3\) and the other
\(4-j\) factors in degree \(2\) gives degree \(8+j\) and rank
\(\binom4j2^{4-j}\).  This is \cref{wb:cusp-cone-B-smash-homology}.
\end{enumerate}
\end{proof}

\begin{theorem}[Exact cone-compactified \(S^{24}\) route]
\hypertarget{tag-036A}{}\label{wb:cusp-cone-S24-route}
\StatementRecord{wb:cusp-cone-S24-route}{proved}{036A}{\SeriesRef{wb:cusp-spec-finite-Seifert-target}, \SeriesRef{wb:cusp-spec-global-circle-circumference}, \SeriesRef{wb:cusp-cone-S12-route}}

There is a continuous surjective based quotient map
\begin{equation}
 q_1:(X,x_0)\longrightarrow(\mathcal C,c_0),\qquad x_0\in W,
 \hypertarget{tag-0379}{}\label{wb:cusp-cone-q1}
\end{equation}
defined as follows:
\begin{enumerate}
\item over \(P\), it is
\((f,\theta_\gamma):f^{-1}(P)\to P\times S^1\), equivalently the
restriction of \(\chi_\gamma\) to \(f^{-1}(P)\);
\item over \(D_j\), \(j=1,2\), it is the finite-filling map
\(N_j\to C_j\) from \cref{wb:cusp-spec-finite-Seifert-target};
\item on \(N_0\setminus W\), writing \(t=re^{i\phi}\), it is
\begin{equation}
 x\longmapsto[r,(e^{i\phi},\theta_\gamma(x))]
 \in\operatorname{Cone}(\partial D_0\times S^1),
 \hypertarget{tag-037A}{}\label{wb:cusp-cone-q1-cusp-formula}
\end{equation}
and every point of \(W\) maps to \(c_0\).
\end{enumerate}
The fourth smash power is a global based map
\begin{equation}
 q_1^{\wedge4}:X^{\wedge4}\longrightarrow\mathcal C^{\wedge4}.
 \hypertarget{tag-0366}{}\label{wb:cusp-cone-S24-map}
\end{equation}
Using \(X\cong_{\mathrm{diff}}S^6\), its source is
\begin{equation}
 X^{\wedge4}\cong(S^6)^{\wedge4}\cong S^{24}.
 \hypertarget{tag-036D}{}\label{wb:cusp-cone-S24-source}
\end{equation}
On four synchronized radial fibres, the canonical product-to-smash quotient
maps restrict to embeddings on the source fibre product and the interior
target-product cross-section.  Under those embeddings,
\cref{wb:cusp-cone-S24-map} restricts exactly to
\begin{equation}
 \chi_{\gamma,T}^{\times4}:F_T^4\longrightarrow C_T^4,\qquad
 C_T=\mathbb R/\ell_T\mathbb Z.
 \hypertarget{tag-0363}{}\label{wb:cusp-cone-S24-fibre-map}
\end{equation}
With its Euclidean \(\ell^2\)-product flat quotient metric,
\begin{equation}
 \operatorname{sys}(C_T^4)=\ell_T
 =T+H-B+O(T^{-1}),\qquad
 (C_T^4,0)\longrightarrow(\mathbb R^4,0)
 \hypertarget{tag-0360}{}\label{wb:cusp-cone-S24-R4-limit}
\end{equation}
in pointed local-isometric, pointed smooth, and pointed
Gromov--Hausdorff topology.

The target homology is
\begin{equation}
 \widetilde H_k(\mathcal C;\mathbb Z)\cong
 \begin{cases}
  \mathbb Z,&k=2,3,\\
  0,&\text{otherwise},
 \end{cases}
 \hypertarget{tag-035D}{}\label{wb:cusp-cone-C-homology}
\end{equation}
and
\begin{equation}
 \widetilde H_k(\mathcal C^{\wedge4};\mathbb Z)\cong
 \begin{cases}
  \mathbb Z,&k=8,12,\\
  \mathbb Z^4,&k=9,11,\\
  \mathbb Z^6,&k=10,\\
  0,&\text{otherwise}.
 \end{cases}
 \hypertarget{tag-035E}{}\label{wb:cusp-cone-C-smash-homology}
\end{equation}
\end{theorem}



\begin{proof}
\begin{enumerate}[label={$\langle1\rangle$\arabic*.},leftmargin=*]
\item The compact spaces \(P\times S^1,C_1,C_2\) are glued along closed boundary
tori by homeomorphisms, producing a compact orientable three-manifold
\(\mathcal M\) with boundary \(\partial D_0\times S^1\).  Attaching the cone
along this closed boundary gives a compact Hausdorff finite CW space
\(\mathcal C\).

\item The overlap identity
\[
 \chi_\gamma\circ h_j=h_j^{S^1}\circ\overline\chi_j
\]
proves that the first two pieces of \(q_1\) agree.  On \(\partial D_0\), the
cone base is glued to the remaining boundary of \(P\times S^1\), so the
first and third pieces agree.  If \(U\) is a neighborhood of \(c_0\), its
inverse image in the cone contains \([0,\delta)\times T^2\) for some
\(\delta>0\), by compactness of the cone base.  Therefore \(q_1^{-1}(U)\)
contains \(f^{-1}(|t|<\delta)\), a neighborhood of \(W\).  This proves
continuity at the new stratum; continuity elsewhere follows from the input
maps and the closed pasting lemma.

\item Every regular circle quotient and both finite Seifert targets are
surjective, and \(W\) maps onto the cone vertex.  Thus \(q_1\) is a
continuous surjection from compact \(X\) to Hausdorff \(\mathcal C\), hence
a quotient map.  It is based, so its fourth smash power exists.  Iterating
\(S^m\wedge S^n\cong S^{m+n}\) gives \cref{wb:cusp-cone-S24-source}.

\item The base point lies in \(W\), while each radial regular fibre is disjoint
from \(W\).  Hence \(F_T^4\) and its product-circle image avoid the closed
source and target fat wedges.  The canonical quotient maps from the source
product and the indicated interior target-product cross-section to their
smash products restrict to embeddings.  Under those embeddings, the induced
smash map restricts to \(\chi_{\gamma,T}^{\times4}\), which itself retains
its displayed nontrivial torus kernel.
The quotient-metric calculation in
\cref{wb:cusp-spec-global-circle-circumference} gives \(\ell_T\).
The product lattice is \(\ell_T\mathbb Z^4\), so the radius-\(R\) argument,
including the shortest-representative proof that the embedded Euclidean ball
is the whole quotient ball, in the proof of \cref{wb:cusp-cone-S12-route} proves
\cref{wb:cusp-cone-S24-R4-limit}.

\item For homology, let \(\rho_0,\rho_1,\rho_2\) be the boundary loops of the pair
of pants, with \(\rho_0+\rho_1+\rho_2=0\), and let \(\eta\) be the regular
target-circle class.  With the boundary-loop and circle orientations used
in the finite-filling presentation, the meridian relations are
\begin{equation}
 3\rho_1-\eta=0,\qquad4\rho_2+\eta=0.
 \hypertarget{tag-036F}{}\label{wb:cusp-cone-Seifert-meridians}
\end{equation}
Reversing the circle orientation reverses both displayed \(\eta\)-signs
and changes none of the following groups.  Thus
\begin{equation}
 H_1(\mathcal M;\mathbb Z)
 =\frac{\mathbb Z\langle\eta,\rho_1,\rho_2\rangle}
 {\langle3\rho_1-\eta,\;4\rho_2+\eta\rangle}
 \cong\mathbb Z\langle g\rangle,
 \hypertarget{tag-035M}{}\label{wb:cusp-cone-M-H1}
\end{equation}
where
\begin{equation}
 \rho_0=-g,\qquad\rho_1=4g,\qquad
 \rho_2=-3g,\qquad\eta=12g.
 \hypertarget{tag-035O}{}\label{wb:cusp-cone-M-boundary-map}
\end{equation}
In particular,
\(H_1(\partial\mathcal M)=\mathbb Z\langle\rho_0,\eta\rangle
\to H_1(\mathcal M)\) is surjective.  The orientable three-manifold
\(\mathcal M\) has one torus boundary, \(H_3(\mathcal M)=0\), and
\(\chi(\mathcal M)=\frac12\chi(\partial\mathcal M)=0\); hence
\(H_2(\mathcal M;\mathbb Q)=0\).  To obtain the integral statement without
suppressing torsion, Poincare--Lefschetz duality and the universal
coefficient theorem give
\[
 H_2(\mathcal M;\mathbb Z)
 \cong H^1(\mathcal M,\partial\mathcal M;\mathbb Z)
 \cong \operatorname{Hom}
 \bigl(H_1(\mathcal M,\partial\mathcal M;\mathbb Z),\mathbb Z\bigr),
\]
because \(H_0(\mathcal M,\partial\mathcal M;\mathbb Z)=0\).  Thus
\(H_2(\mathcal M;\mathbb Z)\) is free; its rank is zero, so it vanishes.

\item The cone attachment is the homotopy cofiber of
\(\partial\mathcal M\hookrightarrow\mathcal M\).  Since the boundary
inclusion is a cofibration,
\[
 \widetilde H_k(\mathcal C;\mathbb Z)
 \cong H_k(\mathcal M,\partial\mathcal M;\mathbb Z).
\]
Poincare--Lefschetz duality and
\(H^0(\mathcal M)=H^1(\mathcal M)=\mathbb Z\),
\(H^2(\mathcal M)=H^3(\mathcal M)=0\), give
\cref{wb:cusp-cone-C-homology}.  The homology is free, so the smash Kunneth
theorem says that four factors of degree \(2\) or \(3\) produce ranks
\(\binom4j\) in degree \(8+j\), proving
\cref{wb:cusp-cone-C-smash-homology}.
\end{enumerate}
\end{proof}

\begin{corollary}[The two-copy rank-two sphere carrier is null-homotopic]
\hypertarget{tag-035Z}{}\label{wb:cusp-cone-S12-sphere-map-null}
\StatementRecord{wb:cusp-cone-S12-sphere-map-null}{proved}{035Z}{\SeriesRef{wb:cusp-cone-sphere-to-sphere-maps}, \SeriesRef{wb:cusp-s12-full-carrier-null}}

After the based identifications in
\cref{wb:cusp-cone-sphere-to-sphere-maps}, the continuous surjective quotient
\[
 \widehat q_3^{\wedge2}:S^{12}\twoheadrightarrow S^6
\]
is based null-homotopic.  In fact, \(g\wedge g:S^{12}\to S^6\) is based
null-homotopic for every based map \(g:S^6\to S^3\).
\end{corollary}



\begin{proof}
\begin{enumerate}[label={$\langle1\rangle$\arabic*.},leftmargin=*]
\item Apply the full external-smash calculation in
\cref{wb:cusp-s12-full-carrier-null} to
\(g=\widehat q_3\).  That theorem proves the stronger assertion that
\(x\wedge y:S^{12}\to S^6\) is null-homotopic for every pair of based
maps \(x,y:S^6\to S^3\).
\end{enumerate}
\end{proof}

\begin{corollary}[Every repeated smash of the circle-quotient carrier is null]
\hypertarget{tag-036E}{}\label{wb:cusp-cone-S24-sphere-map-null}
\StatementRecord{wb:cusp-cone-S24-sphere-map-null}{proved}{036E}{\SeriesRef{wb:cusp-cone-S24-smash-square-factorization}; \cite[Corollary~4.24, p.~360]{Hatcher2002}; \cite[Table~1, p.~113]{IsaksenWangXu2023}}

Put \(f=\widehat q_\gamma:S^6\to S^2\) after the chosen based
identification \(X\cong S^6\).  For every \(r\geq2\),
\begin{equation}
 \bigl[f^{\wedge r}\bigr]=0
 \quad\text{in}\quad
 \pi_{6r}(S^{2r}).
 \hypertarget{tag-0367}{}\label{wb:cusp-cone-S24-null-maps}
\end{equation}
In particular,
\begin{equation}
 \bigl[\widehat q_\gamma^{\wedge2}\bigr]
 =0\in\pi_{12}(S^4),
 \qquad
 \bigl[\widehat q_\gamma^{\wedge4}\bigr]
 =0\in\pi_{24}(S^8).
 \hypertarget{tag-0368}{}\label{wb:cusp-cone-S24-null-special-cases}
\end{equation}
Thus the displayed surjective quotient
\(\widehat q_\gamma^{\wedge4}:S^{24}\twoheadrightarrow S^8\) is globally
null-homotopic.  This does not alter either its point-set surjectivity or the
exact intrinsic \(\mathbb R^4\) limit on the moving four-spheres
\(\mathbb S_{24,T}^4\): those are properties of the specified representative
and its radial restrictions, whereas null-homotopy classifies that
representative only up to based homotopy.
\end{corollary}



\begin{proof}
\begin{enumerate}[label={$\langle1\rangle$\arabic*.},leftmargin=*]
\item Associativity of the smash product gives the
exact factorization
\begin{equation}
 \begin{tikzcd}[column sep=large]
 S^6\wedge S^6
 \arrow[r,"f\wedge\operatorname{id}_{S^6}"]&
 S^2\wedge S^6
 \arrow[r,"\operatorname{id}_{S^2}\wedge f"]&
 S^2\wedge S^2 .
 \end{tikzcd}
 \hypertarget{tag-036C}{}\label{wb:cusp-cone-S24-smash-square-factorization}
\end{equation}
Under the standard based sphere identifications, the first arrow is the
sixfold suspension of \(f\), up to the harmless twist homeomorphisms dictated
by the left-versus-right suspension convention:
\begin{equation}
 f\wedge\operatorname{id}_{S^6}
 =\Sigma^6f:S^{12}\longrightarrow S^8.
 \hypertarget{tag-036B}{}\label{wb:cusp-cone-S24-sixfold-suspension}
\end{equation}
Freudenthal's suspension theorem is already in its isomorphism range here,
because \(12\leq 2\cdot8-2\), and remains in that range after every further
suspension.  It therefore identifies \(\pi_{12}(S^8)\) with the fourth
stable stem.  The low-stem calculation gives
\phantomsection\hypertarget{tag-033R}{}\label{qa:III:layout:11}
\begin{equation}
 \pi_{12}(S^8)\cong\pi_4^{\mathrm S}=0.
 \hypertarget{tag-036R}{}\label{wb:cusp-cone-fourth-stable-stem}
\end{equation}
Here we use \cite[Corollary~4.24, p.~360]{Hatcher2002} and
\cite[Table~1, p.~113]{IsaksenWangXu2023}.
Hence \(\Sigma^6f\) is based null-homotopic, so the composite in
\cref{wb:cusp-cone-S24-smash-square-factorization}, namely
\(f\wedge f\), is based null-homotopic.  For \(r\geq2\), the canonical
associativity homeomorphisms identify
\begin{equation}
 f^{\wedge r}=(f\wedge f)\wedge f^{\wedge(r-2)},
\end{equation}
with the convention \(f^{\wedge0}=\operatorname{id}_{S^0}\).  Smashing a
based null-homotopy with any based map is a based null-homotopy.  This proves
\cref{wb:cusp-cone-S24-null-maps} and \cref{wb:cusp-cone-S24-null-special-cases}.
\end{enumerate}
\end{proof}

\begin{corollary}[Unit-volume normalization does not give
\(\mathbb R^4\)]
\hypertarget{tag-03DH}{}\label{wb:sphere-metric-unit-volume}
\StatementRecord{wb:sphere-metric-unit-volume}{proved}{03DH}{the definitions and constructions stated in the proof}

The four-volume of \(Q_T^2\) is \((\det Y_T)^2\sim T^4\).  Its unit-volume
length factor is therefore \((\det Y_T)^{-1/2}\sim T^{-1}\), and its
unit-volume limit is a square flat four-torus, not \(\mathbb R^4\).
Likewise, the four-volume of \(C_T^4\) is \(\ell_T^4\), and its unit-volume
normalization is exactly the square unit four-torus.
\end{corollary}

\paragraph{Exact comparison with the unmodified source action}
\hypertarget{tag-0382}{}\label{wb:cusp-cover-naive-action-failure}
\StatementRecord{wb:cusp-cover-naive-action-failure}{proved}{0382}{\SeriesRef{wb:cusp-cover-source-factor}}

If one reuses the target action with $v$ in place of $t$ at the source,
then the two sides of equivariance have multiplicative factors
\[
 c_{\bar\lambda}(v)^N v^{NB_0\bar\lambda}
 \quad\hbox{and}\quad
 c_{\bar\lambda}(v^N)v^{NB_0\bar\lambda},
\]
respectively. Equivariance of this unmodified action is exactly the equality $c_{\bar\lambda}(v)^N=c_{\bar\lambda}(v^N)$ for every $\bar\lambda$. The displayed source factor \eqref{wb:cusp-cover-source-factor} satisfies the required equality by taking its specified holomorphic logarithm. For $N=1$ the modified and unmodified actions agree. The explicit
logarithm $2\pi iC(v^N)\bar\lambda/N$ makes this root holomorphic; no
unjustified choice of an $N$th root is involved.

\begin{corollary}[All higher smash powers]
\hypertarget{tag-038T}{}\label{wb:cusp-s12-all-higher-smashes-null}
\StatementRecord{wb:cusp-s12-all-higher-smashes-null}{proved}{038T}{the definitions and constructions stated in the proof}

For every based \(g:S^6\to S^3\) and every \(r\geq2\),
\[
 g^{\wedge r}:S^{6r}\longrightarrow S^{3r}
\]
is based null-homotopic.
\end{corollary}



\begin{proof}
\begin{enumerate}[label={$\langle1\rangle$\arabic*.},leftmargin=*]
\item With the fixed associativity homeomorphisms for smash products,
\[
 g^{\wedge r}=g^{\wedge2}\wedge g^{\wedge(r-2)}.
\]
Smashing a based null-homotopy with a based map gives a based
null-homotopy.
\end{enumerate}
\end{proof}

\paragraph{Scope}
\hypertarget{tag-038W}{}\label{wb:cusp-s12-nullity-scope}
\StatementRecord{wb:cusp-s12-nullity-scope}{proved}{038W}{the definitions and constructions stated in the proof}

The theorem changes no point-set or metric statement.  A surjective quotient
map may be null-homotopic, and the embedded moving four-spheres and their
intrinsic pointed \(\mathbb R^4\)-limits remain exactly as constructed.  The
theorem concerns the sphere-valued postcomposition
\(\widehat q_3^{\wedge2}\); it does not imply null-homotopy of the earlier
conical-target map
\(q_2^{\wedge2}:S^{12}\to\mathcal A^{\wedge2}\).

new_text:
\begin{theorem}[invariant-Chern additive caps]\hypertarget{tag-02LT}{}\label{maps:src:D.2.51}
\textnormal{\small tag 02LT.}


Let $K$ be the reduced central fibre of an original additive
Kodaira neighbourhood, of type
$II,III,IV,IV^*,III^*,I_1^*$ or $I_3^*$.
Write its rational components as $C_i$, its primitive
multiplicity vector as $\mu=(\mu_i)$, and let $\sigma$
be the actual component permutation induced by the section $Q$.
Let the original line bundle have invariant component degrees
$c_i$, so that
\begin{equation}
                  \sigma c=c,\qquad \sum_i\mu_i c_i=0.
                                                        \hypertarget{tag-01ZY}{}\label{maps:eq:D.IC1}
\end{equation}
These include every corrected line bundle in \ref{maps:src:D.2.50}.
Let the component orbits be $O_1,\ldots,O_\rho$, with
lengths $l_j$ and common degrees $c_j$ on $O_j$.
For $c\ne0$ put
\begin{equation}
                  g=\gcd_j(c_j),\qquad
                  h=\gcd_j(l_jc_j),
                                                        \hypertarget{tag-01ZZ}{}\label{maps:eq:D.IC2}
\end{equation}
where both gcds are positive. For the resulting original
six-dimensional cap $U$, there is an exact integral cellular
cone, with its actual circle-fibre and regular-area classes,
\begin{equation}
\begin{gathered}
 C_0=\mathbb Z,\quad C_1=\mathbb Z^2,\quad
 C_2=\mathbb Z^v\oplus\mathbb Zt,\quad
 C_3=\mathbb Z^v\oplus\mathbb Z^v,\quad C_4=\mathbb Z^v,\\
 d_2=\begin{pmatrix}c^t&0\\0&0\end{pmatrix},\qquad
 d_3=\begin{pmatrix}0&\sigma-I\\0&c^t\end{pmatrix},\qquad
 d_4=\begin{pmatrix}I-\sigma\\0\end{pmatrix}.
\end{gathered}                                             \hypertarget{tag-0200}{}\label{maps:eq:D.IC3}
\end{equation}
The degree-one generators are the scalar circle $\delta$
and a positive long circle $\gamma$. In particular
\begin{equation}
\begin{array}{c|ccccc}
i&0&1&2&3&4\\\hline
H_i(U;\mathbb Z)&\mathbb Z&
\mathbb Z\oplus\mathbb Z/g&
\mathbb Z^{\rho-1}\oplus\mathbb Z/h&
\mathbb Z^{2\rho-1}&\mathbb Z^\rho .
\end{array}                                               \hypertarget{tag-0201}{}\label{maps:eq:D.IC4}
\end{equation}
Moreover $\pi_1(U)=\mathbb Z\oplus\mathbb Z/g$.
When $c=0$, these groups are instead
\begin{equation}
 (H_0,H_1,H_2,H_3,H_4)=
 (\mathbb Z,\mathbb Z^2,\mathbb Z^{\rho+1},
                         \mathbb Z^{2\rho},\mathbb Z^\rho).
                                                        \hypertarget{tag-0202}{}\label{maps:eq:D.IC5}
\end{equation}
The actual regular-fibre torus $\delta\wedge\gamma$
maps to the class of $t$ in \eqref{maps:eq:D.IC3}, which generates
\emph{all} of the cyclic torsion $\mathbb Z/h$ when
$c\ne0$. The elliptic tori crossed with $\delta$ map
to zero. The complex elliptic area maps to the literal
cycle $(\mu,0)$ in \eqref{maps:eq:D.IC3}.

Let $B$ be the elliptic monodromy, $q$ its marked
$Q$-cocycle, and $z=(B-I)^{-1}q$. Put
\begin{equation}
        q_Q=\gcd_j(l_j\mu_j)
             =\operatorname{ord}(\overline Q).
                                                        \hypertarget{tag-0203}{}\label{maps:eq:D.IC6}
\end{equation}
The actual logarithm $z$ has exact denominator $q_Q$.
For $c\ne0$, the full regular-fibre image in $H_2(U)$
is $\mathbb Z\oplus\mathbb Z/h$ with free cokernel
of rank $\rho-2$. For $c=0$ it is a primitive
$\mathbb Z^2$ with free cokernel of rank $\rho-1$.
In both cases this is already the full boundary image.
Consequently the full boundary kernel projects onto
all of $\operatorname{Fix}(A)$ in the Wang sequence.


If $h=1$, these facts determine the complete marked
local kernels. In the regular basis
$(e_1,e_2,\delta,\gamma)$ the actual fibre kernel is
\begin{equation}
 \ker\bigl(q_Q(1,0,z_2,0,-z_1,0):\mathbb Z^6\to\mathbb Z\bigr),
                                                        \hypertarget{tag-0204}{}\label{maps:eq:D.IC7}
\end{equation}
where the six coordinates have their usual increasing
exterior order. Both literal fixed-normal tori bound.
The cap kills every vertical fundamental-group
coordinate and retains the primitive $\gamma$.
This includes the following star degrees from Theorem~\ref{maps:src:D.2.50}:
\begin{equation}
 \begin{array}{c|c}
 I_1^*&(1,1,0,0,-1,0)\\
 I_3^*&(1,1,0,0,-1,0,0,0)
 \end{array}
                                                        \hypertarget{tag-0205}{}\label{maps:eq:D.IC8}
\end{equation}
for component classes $P=Q=2$ in $\mathbb Z/4$.
Their actual permutation has two paired outer orbits
and fixed inner components, and $g=h=1$.

For $h>1$, the cone determines a torsion coordinate from the
cellular representative of a marked torus. The individual torsion
coordinates of the two mixed elliptic--long tori and the second
fixed-normal torus require those representatives. The image and
cokernel assertions above hold for every invariant degree vector;
the complete marked-kernel assertion is in the sector $h=1$.

\end{theorem}

